#include "PhysicsStudy.h"
namespace cocos2d { bool Physics3DWorldStudy::rayCast(const std::vector<HitResultStudy>& hits, float maxDistance, HitResultStudy& result) const { bool found=false; for (const auto& hit : hits) if (hit.distance<=maxDistance && (!found || hit.distance<result.distance)) { result=hit; found=true; } return found; } void runLesson() { Physics3DWorldStudy world; HitResultStudy result{}; std::vector<HitResultStudy> hits{{"Wall",6,6,-1},{"Crate",4,4,-1}}; if (world.rayCast(hits,10,result)) std::cout << "hit " << result.name << " @ " << result.distance << ", normal=" << result.normal << "\n"; } }
